import{_ as e,o as r,c as s,a2 as t}from"./chunks/framework.BWuWLRhz.js";const b=JSON.parse('{"title":"Historial","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/history.md","filePath":"es-ES/user-guide/settings/history.md","lastUpdated":1786537234000}'),o={name:"es-ES/user-guide/settings/history.md"};function i(l,a,d,n,c,u){return r(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="historial" tabindex="-1">Historial <a class="header-anchor" href="#historial" aria-label="Permalink to &quot;Historial&quot;">​</a></h1><p>Dos pestañas, cada una independiente: <strong>Historial de búsqueda</strong> e <strong>Historial de palabras clave</strong>.</p><h2 id="historial-de-busqueda" tabindex="-1">Historial de búsqueda <a class="header-anchor" href="#historial-de-busqueda" aria-label="Permalink to &quot;Historial de búsqueda&quot;">​</a></h2><p>Registra los resultados que realmente has abierto, para que se puedan priorizar la próxima vez que busques algo similar.</p><p>El Historial de búsqueda recuerda tanto la ruta abierta como la consulta que llevó hasta ella. Una coincidencia difusa posterior con esa consulta registrada puede recuperar y priorizar la ruta existente en las ventanas de búsqueda rápida, integrada y completa; por ejemplo, abrir <code>BCompare.exe</code> con <code>bcomp</code> permite que <code>bc</code> vuelva a mostrarlo cerca del principio. La búsqueda integrada conserva las coincidencias dentro de la carpeta activa en <strong>Carpeta actual</strong> y coloca las demás en <strong>Búsqueda global</strong>; las rutas que ya no existen se ignoran y cada ruta solo aparece una vez.</p><ul><li>Casilla <strong>Habilitar historial</strong> — activa/desactiva el registro; las entradas existentes se conservan aunque lo desactives, simplemente dejan de añadirse nuevas.</li><li><strong>Cuadro de búsqueda</strong> — filtra la lista de historial visible por palabra clave.</li><li>Cada entrada se puede eliminar individualmente, o todas a la vez con <strong>Borrar todo el historial</strong>.</li></ul><h2 id="historial-de-palabras-clave" tabindex="-1">Historial de palabras clave <a class="header-anchor" href="#historial-de-palabras-clave" aria-label="Permalink to &quot;Historial de palabras clave&quot;">​</a></h2><p>Registra el texto en bruto que has escrito en el cuadro de búsqueda de la ventana rápida (no lo que abriste), para que puedas recorrer hacia atrás tus consultas recientes con los <a href="./../hotkeys.html#atajos-globales">atajos del historial de palabras clave</a> (<code>Alt+Arriba</code> / <code>Alt+Abajo</code> por defecto).</p><ul><li>El mismo interruptor <strong>Habilitar historial</strong>, filtro de búsqueda, eliminación por entrada, y botón <strong>Borrar todo el historial</strong>, pero centrado en palabras clave en lugar de en resultados abiertos.</li></ul>',9)])])}const h=e(o,[["render",i]]);export{b as __pageData,h as default};
